const outcomes=['Attend consistently','Join a small group','Serve in ministry','Give consistently','Invite a friend','Follow Jesus','Be baptized','Become a member','Make a disciple','Step into leadership','Pray consistently','Read Scripture','Strengthen family','Reconcile','Find healing','Discover SHAPE','Live on mission','Share faith','Develop leaders','Practice generosity','Grow pastor social presence'];
const sermons=[['Your Part Matters','Discover the Ministry God Designed You to Do','1 Corinthians 12:12–27','Serve in ministry','serving gifts volunteer'],['Better Together','Why No One Grows Alone','Hebrews 10:24–25','Join a small group','community groups belonging'],['Open Hands','Discovering the Freedom of Generosity','2 Corinthians 9:6–11','Give consistently','money stewardship finances'],['For the One','Seeing the Person God Has Put in Front of You','Luke 15:1–7','Invite a friend','evangelism easter outreach'],['Come Home','The Father Is Still Waiting for You','Luke 15:11–32','Follow Jesus','gospel salvation grace'],['Raised to Life','What Baptism Says About Your New Story','Romans 6:1–4','Be baptized','baptism obedience'],['This Is Home','Moving From Attending to Belonging','Ephesians 2:19–22','Become a member','membership commitment'],['You and Who?','Who Are You Helping Follow Jesus?','2 Timothy 2:2','Make a disciple','discipleship mentoring'],['Step Up','When God Invites You to Lead','Joshua 1:6–9','Step into leadership','leadership apprentice'],['Teach Us to Pray','Building a Life of Conversation With God','Luke 11:1–4','Pray consistently','prayer'],['Open the Book','Why God’s Word Still Changes Lives','Psalm 119:105','Read Scripture','bible study'],['Live Sent','Seeing Everyday Life as Mission','John 20:21','Live on mission','mission great commission']];
let active='',currentStep=1,currentBuild=null,currentBook='weekend';const el=id=>document.getElementById(id);
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>el(b.dataset.go).scrollIntoView({behavior:'smooth'})));
outcomes.slice(0,10).forEach(x=>{const b=document.createElement('button');b.className='chip';b.textContent=x;b.addEventListener('click',()=>{active=active===x?'':x;document.querySelectorAll('.chip').forEach(c=>c.classList.toggle('on',c.textContent===active));render()});el('chips').appendChild(b)});outcomes.forEach(x=>el('bo').insertAdjacentHTML('beforeend',`<option>${x}</option>`));
function render(){const q=el('q').value.toLowerCase();let r=sermons.filter(s=>(!q||s.join(' ').toLowerCase().includes(q))&&(!active||s[3]===active));if(!r.length)r=sermons.slice(0,4);el('results').innerHTML=r.slice(0,6).map(s=>`<div class="result"><div><h3>${s[0]}</h3><p>${s[1]} · ${s[2]}</p><button class="secondary darkText customize" data-i="${sermons.indexOf(s)}">Customize this sermon</button></div><span class="tag">${s[3]}</span></div>`).join('');document.querySelectorAll('.customize').forEach(b=>b.onclick=()=>{const s=sermons[+b.dataset.i];document.querySelector('[name=theme]').value=s[0];el('bo').value=s[3];el('build').scrollIntoView({behavior:'smooth'})})}
el('searchBtn').onclick=render;render();

const stepFields={1:['a','b'],2:['c','d'],3:['e','f'],4:['g','h'],5:['i','j'],6:['k','l'],7:['m','n']};
const unlockCopy={0:['Starter Curator','Find sermons and build a basic blueprint.','Add your pastoral voice to make sermon language more authentic.'],1:['Voice-Aware Curator','Outlines and scripts can now reflect your preaching tone and calling.','Add theology to strengthen interpretive and application guardrails.'],2:['Theology-Aware Curator','Text, gospel and application recommendations can honor your convictions.','Add church context to customize illustrations and next steps.'],3:['Church-Aware Curator','Applications can now fit your mission, people and congregational moment.','Add your sermon library to unlock memory, stories and gap analysis.'],4:['Library-Aware Curator','Curator can account for what you have preached and mine your own stories.','Add outcomes so the system knows where you want people to move.'],5:['Outcome-Aware Curator','Sermons can now be reverse-engineered toward clearer faithful responses.','Add your calendar to build a 6–12 month formation strategy.'],6:['Formation Curator','Series recommendations can account for seasons, catalytic Sundays and ministry rhythms.','Add your public presence to turn every sermon into a weekly reach strategy.'],7:['Full Pastor Intelligence','Your sermon, church, calendar and public voice are now connected into one weekly operating system.','Keep adding sermons, stories and outcomes; Curator improves with use.']};
function fieldComplete(name){const x=document.querySelector(`[name=${name}]`);return x&&x.value.trim().length>=20}
function completedSteps(){let n=0;for(let s=1;s<=7;s++){if(stepFields[s].every(fieldComplete))n++;}return n}
function profilePercent(){const names=Object.values(stepFields).flat();return Math.round(names.filter(fieldComplete).length/names.length*100)}
function refreshProfile(){const done=completedSteps(),pct=profilePercent(),levels=['Starter','Voice','Theology','Church','Library','Outcomes','Formation','Full Intelligence'];el('profileLevel').textContent=levels[done];el('profileScore').textContent=pct+'%';el('meterFill').style.width=pct+'%';document.querySelectorAll('.step').forEach(b=>{const s=+b.dataset.step;b.classList.toggle('on',s===currentStep);b.classList.toggle('done',s<currentStep&&stepFields[s].every(fieldComplete))});const c=unlockCopy[done];el('unlockTitle').textContent=c[0];el('unlocks').innerHTML=`<div><strong>Unlocked</strong><span>${c[1]}</span></div><div><strong>Next improvement</strong><span>${c[2]}</span></div>`;el('summary').innerHTML=`<strong>${pct}% of your Pastor Intelligence Profile is ready.</strong><br>Every completed layer improves sermon customization, weekly formation outputs and recommendations.`}
function showStep(n){currentStep=Math.max(1,Math.min(7,n));document.querySelectorAll('.profilePane').forEach(p=>p.classList.toggle('on',+p.dataset.pane===currentStep));document.querySelectorAll('.step').forEach(b=>b.classList.toggle('on',+b.dataset.step===currentStep));el('prevStep').style.visibility=currentStep===1?'hidden':'visible';el('nextStep').style.display=currentStep===7?'none':'inline-block';el('finishProfile').style.display=currentStep===7?'inline-block':'none';refreshProfile()}
document.querySelectorAll('.step').forEach(b=>b.onclick=()=>showStep(+b.dataset.step));el('prevStep').onclick=()=>showStep(currentStep-1);el('nextStep').onclick=()=>showStep(currentStep+1);el('pf').oninput=refreshProfile;el('pf').onsubmit=e=>{e.preventDefault();refreshProfile();el('summary').innerHTML=`<strong>Profile saved for this prototype session.</strong><br>Your next sermon build will use the intelligence layers you completed. Production will persist this securely to your pastor account.`};showStep(1);

function visible(o){const m={'Serve in ministry':'Select a ministry, a role and a first serving date.','Join a small group':'Choose a group and register before leaving the service.','Give consistently':'Set a specific regular giving commitment.','Invite a friend':'Name one person and send an invitation this week.','Make a disciple':'Name one person and put the first meeting on the calendar.','Be baptized':'Register for the next baptism opportunity.','Grow pastor social presence':'Publish one sermon clip plus a daily devotional sequence that recruits people back into the journey.'};return m[o]||`Take one observable, calendar-based next step toward ${o.toLowerCase()}.`}
function dailyScripts(theme,outcome){return [
['Monday','REMEMBER',`Yesterday we talked about ${theme}. Here is the one idea I do not want you to lose today: God's truth is meant to move from something we hear to something we live. Take ninety seconds and ask: where is this already touching my life? Before the day gets away from you, name one place where you need to respond. Then take one small step toward ${outcome.toLowerCase()}. If this is helping you, invite one person to walk through the week with you.`],
['Tuesday','PRACTICE',`Today I want to make Sunday's message practical. Think about ${theme}. What is one action you can take before tonight that makes this truth visible? Do not make it complicated. Choose the smallest faithful next step. Put it on the calendar, send the text, have the conversation, sign up, or begin the practice. Formation grows when truth becomes action. And if someone comes to mind, invite them to take the step with you.`],
['Wednesday','TOGETHER',`Midweek is where good intentions often fade, so today bring someone else into the journey. Share one thing from ${theme} that challenged you. Ask them what stood out to them. Pray together for one minute. Christianity was never designed as a solo project. The question today is simple: who is your Who? Who can help you live this, and who might you help take the same next step?`],
['Thursday','SERVE',`A message becomes ministry when it moves beyond us. Today ask: who could experience God's love because I took ${theme} seriously? Look for one person you can encourage, serve, include, forgive, help or invite. You do not need a platform. You need a person. Let today's next step turn Sunday's truth outward.`],
['Friday','SHARE',`Before the week ends, tell the story. What has God been showing you through ${theme}? You do not need a polished testimony. Share one sentence about what you are learning and one step you are trying to take. Your story may become someone else's invitation. If this week's journey has helped you, send today's video to one person and invite them to join us this weekend.`],
['Saturday','PREPARE',`Tomorrow we gather again. Before Sunday arrives, look back over the week. Where did ${theme} become more than an idea? What changed? Where did you resist? What do you want God to continue? Write down one sentence. Then come tomorrow ready not only to receive another message, but to keep building a life of faithful next steps. Bring someone with you if you can.`]
]}
function devotional(theme,outcome){const d=dailyScripts(theme,outcome);el('devos').innerHTML=d.map(x=>`<div class="day"><small>${x[0]} · ${x[1]}</small><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}
function servicePlan(theme,outcome){return [
['Opening','2 min',`Countdown + visual question tied to ${theme}.`],['Worship','12 min','Begin with celebration, then move toward the emotional/theological tone of the message.'],['Welcome','3 min',`Welcome guests and frame why ${theme} matters this week.`],['Story/Testimony','4 min',`Use a real congregation story that illustrates movement toward ${outcome.toLowerCase()}.`],['Sermon','28 min',`Teach the text faithfully; make the outcome explicit without forcing the text.`],['Response','6 min',`Give one observable next step: ${visible(outcome)}`],['Send','3 min','Invite people into the daily devotional journey and next Sunday.'],['Buffer','2 min','Protect timing and transitions.']
]}
function socialItems(theme,outcome){return [
['Pre-Sunday teaser',`Question hook: “What if ${theme.toLowerCase()} is not mainly something to understand—but something God wants to change in us?”`],
['Primary sermon clip',`Select the 20–45 second moment where the sermon moves from truth to ${outcome.toLowerCase()}. Add captions and one clear invitation.`],
['Monday devotional',`90-second vertical video: REMEMBER. CTA: join the six-day journey.`],
['Wednesday clip',`90-second vertical video: TOGETHER. CTA: send this to your Who.`],
['Friday invitation',`Story/reel: what are you learning this week? CTA: share + invite someone Sunday.`],
['Saturday recruit',`15–30 second invitation to the next message, group, baptism, serving step or journey.`]
]}
function groupItems(theme,outcome){return [
['Small-group opener',`What phrase or moment from ${theme} stayed with you after Sunday?`],
['Discussion',`Where is this truth easiest to agree with but hardest to practice?`],
['Practice',visible(outcome)],
['You + Who?',`Name one person who can take this step with you or whom you can help this week.`],
['Family table',`In one sentence, explain ${theme} to someone younger than you. What would it look like in our home this week?`],
['Leader prompt','End by identifying the next person who could lead the discussion or help facilitate next week.']
]}
function seriesItems(theme,outcome){return [
['Week 1 · SEE',`Why ${theme} Matters`,'Establish the biblical truth and expose the formation gap.'],['Week 2 · START','Take the First Step',`Move from agreement to one observable practice toward ${outcome.toLowerCase()}.`],['Week 3 · SHARE','Practice It Together','Use groups, families and You + Who? relationships.'],['Week 4 · MULTIPLY','Pass It On','Help someone else take the same next step.']
]}
function measureItems(outcome){return [
['Designed outcome',outcome],['Response','How many people indicated an immediate next step?'],['Activation','How many actually began the behavior or ministry pathway?'],['Retention','How many were still practicing/participating after 30 days?'],['Story','What qualitative testimonies describe meaningful formation?'],['Multiplication','How many invited, led, served, discipled or developed someone else?']
]}
function renderPlaybook(type=currentBook){currentBook=type;document.querySelectorAll('#playbookTabs button').forEach(b=>b.classList.toggle('on',b.dataset.book===type));if(!currentBuild){el('playbookBody').innerHTML='<div class="emptyBook">Build a sermon above to generate the complete playbook.</div>';return}const {theme,outcome}=currentBuild;let html='';if(type==='weekend')html=`<div class="bookGrid">${servicePlan(theme,outcome).map(x=>`<div class="bookItem"><small>${x[1]}</small><h3>${x[0]}</h3><p>${x[2]}</p></div>`).join('')}<div class="bookItem"><small>WELCOME COPY</small><h3>60-second welcome</h3><p>“Welcome. If you are new, we are glad you are here. Today we are talking about ${theme}—not simply as an idea, but as a truth that can shape the way we live this week. Before we leave, we will give you one clear next step and a simple way to keep the journey going Monday through Saturday.”</p></div><div class="bookItem"><small>COMMUNICATION CARD</small><h3>My next step</h3><p>${visible(outcome)}</p></div><div class="bookItem"><small>BULLETIN</small><h3>Insert outline</h3><p>Title · Scripture · Big Idea · 4-point outline · notes · weekly practice · QR/next-step copy.</p></div></div>`;
if(type==='daily')html=`<div class="bookGrid">${dailyScripts(theme,outcome).map(x=>`<div class="bookItem"><small>${x[0]} · ${x[1]}</small><h3>~90-second teleprompter script</h3><p>${x[2]}</p></div>`).join('')}</div>`;
if(type==='social')html=`<div class="bookGrid">${socialItems(theme,outcome).map(x=>`<div class="bookItem"><small>SOCIAL</small><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div>`;
if(type==='groups')html=`<div class="bookGrid">${groupItems(theme,outcome).map(x=>`<div class="bookItem"><small>FORMATION</small><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div>`;
if(type==='series')html=`<div class="bookGrid">${seriesItems(theme,outcome).map(x=>`<div class="bookItem"><small>${x[0]}</small><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div>`;
if(type==='measure')html=`<div class="bookGrid">${measureItems(outcome).map(x=>`<div class="bookItem"><small>INTELLIGENCE</small><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div>`;el('playbookBody').innerHTML=html}
document.querySelectorAll('#playbookTabs button').forEach(b=>b.onclick=()=>renderPlaybook(b.dataset.book));

el('bf').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries()),v=d.visible||visible(d.outcome);currentBuild=d;el('out').innerHTML=`<div class="ey">Sermon intelligence blueprint</div><h3>${d.theme}</h3><div class="summary">Faithful preaching of ${d.theme} should lead toward ${d.outcome.toLowerCase()} through a clear, text-aligned next step.</div><p><strong>Textual integrity:</strong> Confirm the passage's primary meaning before finalizing the outcome. The outcome must come through the text, not be imposed on it.</p><p><strong>Pastor profile:</strong> Current profile completion: ${profilePercent()}%. The more profile layers completed, the more accurately production can align voice, theology, church context, sermon memory and calendar.</p><p><strong>Video-camera next step:</strong> ${v}</p><p><strong>Weekend intelligence:</strong> A proposed service order, welcome, response moment, communication-card copy and bulletin outline have been created.</p><p><strong>Daily formation:</strong> Six ~90-second weekday teleprompter scripts have been created for a single weekly recording block.</p><p><strong>Social presence:</strong> The playbook identifies sermon clip moments, daily devotional hooks and invitation posts.</p><p><strong>Groups + family:</strong> Discussion, practice and You + Who? prompts extend Sunday relationally.</p>`;devotional(d.theme,d.outcome);const a=seriesItems(d.theme,d.outcome);el('series').innerHTML=a.map(x=>`<div class="week"><small>${x[0]}</small><h3>${x[1]}</h3><p>${x[2]}</p><strong>${d.outcome}</strong></div>`).join('');el('socialPlan').innerHTML=socialItems(d.theme,d.outcome).slice(0,4).map(x=>`<div class="week"><small>SOCIAL</small><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('');renderPlaybook('weekend');el('playbook').scrollIntoView({behavior:'smooth'})};

const months=['January','February','March','April','May','June','July','August','September','October','November','December'];function calendar(seed=false){const x=seed?[['Prayer + Renewal','Dependence on God'],['Community','Belonging + groups'],['Invitation','Build toward Easter'],['Easter + Gospel','Gospel + baptism'],['Serving + SHAPE','Mobilize ministry'],['Family + Rhythms','Faith at home'],['Wisdom + Rest','Summer formation'],['Vision + Preparation','Prepare fall launch'],['Groups + Growth','Churchwide journey'],['Leadership','Develop multipliers'],['Generosity','Stewardship + gratitude'],['Hope + Mission','Christmas + year-end mission']]:months.map(()=>['Open season','Add a sermon or series priority']);el('planner').innerHTML=months.map((m,i)=>`<div class="month"><small>${m}</small><h3>${x[i][0]}</h3><p>${x[i][1]}</p></div>`).join('')}el('seedBtn').onclick=()=>calendar(true);calendar();